import{_ as n,o as h,c as o,a2 as e}from"./chunks/framework.2Es64uX1.js";const l=JSON.parse('{"title":"Review: Đề xuất bổ sung Chương 1 KTPMUD — 1.5.4 Agentic SDLC","description":"","frontmatter":{"title":"Review: Đề xuất bổ sung Chương 1 KTPMUD — 1.5.4 Agentic SDLC","document_id":"KTPMUD-CH01-AGENTIC-SDLC-REVIEW-20261102","author_owner":"Claude (review độc lập theo yêu cầu người dùng)","version":"1.0.0","date":"2026-11-02","timezone":"Asia/Ho_Chi_Minh","status":"Review — đã tự kiểm chứng trực tiếp nguồn gốc; chưa phải quyết định thẩm định cuối","language":"vi","repository":"fossbk-spec/KTPMUD","target_path":"docs/reviews/KTPMUD_CH01_Agentic_SDLC_Review_v1.0.0_20261102.md","supersedes":null,"reviews_of_proposal":"docs/proposals/KTPMUD_Proposal_CH01_Agentic_SDLC_2026_v0.1.0_20261102.md"},"headers":[],"relativePath":"reviews/KTPMUD_CH01_Agentic_SDLC_Review_v1.0.0_20261102.md","filePath":"reviews/KTPMUD_CH01_Agentic_SDLC_Review_v1.0.0_20261102.md","lastUpdated":1793573724000}'),i={name:"reviews/KTPMUD_CH01_Agentic_SDLC_Review_v1.0.0_20261102.md"};function c(r,t,g,a,d,u){return h(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="review-đe-xuat-bo-sung-chuong-1-ktpmud-—-tieu-muc-1-5-4-agentic-sdlc" tabindex="-1">Review: Đề xuất bổ sung Chương 1 KTPMUD — Tiểu mục 1.5.4 Agentic SDLC <a class="header-anchor" href="#review-đe-xuat-bo-sung-chuong-1-ktpmud-—-tieu-muc-1-5-4-agentic-sdlc" aria-label="Permalink to &quot;Review: Đề xuất bổ sung Chương 1 KTPMUD — Tiểu mục 1.5.4 Agentic SDLC&quot;">​</a></h1><h2 id="thong-tin-tai-lieu" tabindex="-1">Thông tin tài liệu <a class="header-anchor" href="#thong-tin-tai-lieu" aria-label="Permalink to &quot;Thông tin tài liệu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trường</th><th>Giá trị</th></tr></thead><tbody><tr><td>Phiên bản</td><td>1.0.0</td></tr><tr><td>Ngày</td><td>02/11/2026</td></tr><tr><td>Trạng thái</td><td>Review — đã tự kiểm chứng trực tiếp; chưa phải quyết định thẩm định cuối</td></tr><tr><td>Tác giả</td><td>Claude (review độc lập theo yêu cầu người dùng)</td></tr><tr><td>Repo đích</td><td><code>fossbk-spec/KTPMUD</code></td></tr><tr><td>Review đối với</td><td><code>docs/proposals/KTPMUD_Proposal_CH01_Agentic_SDLC_2026_v0.1.0_20261102.md</code></td></tr></tbody></table><h2 id="_1-pham-vi-review" tabindex="-1">1. Phạm vi review <a class="header-anchor" href="#_1-pham-vi-review" aria-label="Permalink to &quot;1. Phạm vi review&quot;">​</a></h2><p>Đề xuất mời chèn tiểu mục 1.5.4 (Agentic SDLC) vào <code>chapters/ch01_tong_quan_sdlc.md</code>, trích dẫn báo cáo <em>2026 Agentic Coding Trends Report</em> của Anthropic. Vì nội dung chèn ngay sau §1.5.3 (mục cảnh báo chính cuốn sách về rủi ro ảo giác/package hallucination của AI), tôi không chỉ đọc đề xuất mà <strong>tải trực tiếp file PDF nguồn</strong> (<code>https://resources.anthropic.com/hubfs/2026%20Agentic%20Coding%20Trends%20Report.pdf</code>, 834.5KB, có thật) và trích xuất text (<code>pdftotext</code>) để đối chiếu từng số liệu/thuật ngữ, theo đúng nguyên tắc không tin một claim nếu chưa tự xác minh.</p><h2 id="_2-ket-qua-tu-kiem-chung" tabindex="-1">2. Kết quả tự kiểm chứng <a class="header-anchor" href="#_2-ket-qua-tu-kiem-chung" aria-label="Permalink to &quot;2. Kết quả tự kiểm chứng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Claim trong đề xuất</th><th>Đối chiếu với PDF gốc</th><th>Kết luận</th></tr></thead><tbody><tr><td>1</td><td>&quot;60% công việc hàng ngày, 0–20% full delegate&quot;</td><td>PDF dòng 67-68 &amp; 256-259: &quot;...use AI in roughly 60% of their work... &#39;fully delegate&#39; only 0-20% of tasks&quot;</td><td><strong>CONFIRMED</strong> — khớp chính xác</td></tr><tr><td>2</td><td>Case study Augment Code (Claude): dự án CTO ước 4-8 tháng, hoàn thành trong 2 tuần</td><td>PDF dòng 149-155: &quot;...estimated would take 4 to 8 months in just two weeks using Augment Code, powered by Claude&quot;</td><td><strong>CONFIRMED</strong> — khớp chính xác, đúng cả tên công ty và việc gán công cho Claude</td></tr><tr><td>3</td><td>Thuật ngữ &quot;Dynamic Surge Staffing&quot;</td><td>PDF dòng 143: <code>One manifestation we envision is dynamic &quot;surge&quot; staffing</code></td><td><strong>CONFIRMED</strong> — đúng thuật ngữ gốc</td></tr><tr><td>4</td><td>&quot;Kỹ sư giỏi nhất học bằng con đường khổ luyện (the hard way)&quot;</td><td>PDF dòng 243: <code>&quot;I developed that ability by doing software engineering &#39;the hard way.&#39;&quot;</code></td><td><strong>CONFIRMED</strong> — diễn giải trung thực, dù PDF trình bày như lời 1 kỹ sư cụ thể chứ không phải kết luận chung của Anthropic (sắc thái nhỏ, không sai)</td></tr><tr><td>5</td><td>Tiêu đề report, @techreport URL</td><td>PDF trang 1: &quot;2026 Agentic Coding Trends Report / How coding agents are reshaping software development&quot;</td><td><strong>CONFIRMED</strong> — khớp chính xác, URL tải được thật</td></tr><tr><td>6</td><td>&quot;Một kỹ sư mới gia nhập thường mất từ <strong>2 đến 8 tuần</strong>&quot; (mục 3, Onboarding)</td><td>PDF chỉ nói onboarding &quot;collapse from weeks to hours&quot; — <strong>không có con số 2–8 tuần ở đâu trong toàn văn report</strong> (đã <code>grep</code> toàn bộ 442 dòng text trích xuất)</td><td><strong>DISPUTED — số liệu bị thêm vào, không có trong nguồn.</strong> Xem mục 3 dưới</td></tr><tr><td>7</td><td>&quot;Cycle Time Collapse&quot; trình bày như tên trào lưu chính thức</td><td>PDF dùng câu mô tả &quot;collapse cycle time from weeks to hours&quot;, KHÔNG dùng cụm này như tên mục/trào lưu chính thức (khác với &quot;The collaboration paradox&quot; và &quot;Role transformation: From implementer to orchestrator&quot; — đây mới là tên mục thật trong PDF)</td><td><strong>DISPUTED (nhẹ)</strong> — không sai sự kiện, nhưng đề xuất &quot;chính thức hóa&quot; một cụm diễn giải thành tên trào lưu, gây cảm giác trích dẫn chặt hơn thực tế</td></tr><tr><td>8</td><td>Vị trí chèn &quot;sau dòng 540&quot;</td><td><code>grep -n</code> xác nhận §1.5.3 kết thúc dòng ~539, &quot;Bảng tổng kết&quot; bắt đầu dòng 542</td><td><strong>CONFIRMED</strong> chính xác</td></tr><tr><td>9</td><td>Citekey <code>@anthropic2026agentic</code> chưa trùng</td><td><code>grep</code> <code>references/library.bib</code> → không có kết quả</td><td><strong>CONFIRMED</strong> không trùng</td></tr><tr><td>10</td><td>Thuật ngữ nhất quán với sách (Bàn giao, CAMS, Dr May Day v2.0)</td><td><code>grep</code> file đích: &quot;Bàn giao (Handoffs)&quot; dòng 364, &quot;mô hình CAMS&quot; dòng 407, &quot;Dr May Day v2.0&quot; dùng xuyên suốt</td><td><strong>CONFIRMED</strong> nhất quán</td></tr></tbody></table><h2 id="_3-phat-hien-can-sua-truoc-khi-tham-đinh" tabindex="-1">3. Phát hiện cần sửa trước khi thẩm định <a class="header-anchor" href="#_3-phat-hien-can-sua-truoc-khi-tham-đinh" aria-label="Permalink to &quot;3. Phát hiện cần sửa trước khi thẩm định&quot;">​</a></h2><p><strong>3.1. Số liệu &quot;2 đến 8 tuần&quot; (mục 3, Onboarding) không có trong nguồn — cần sửa hoặc gỡ.</strong> Đề xuất viết: &quot;một kỹ sư mới gia nhập thường mất từ 2 đến 8 tuần chỉ để đọc hiểu kiến trúc&quot;. Report gốc chỉ nói chung &quot;collapse from weeks to hours&quot;, không đưa ra khoảng số cụ thể nào cho thời gian onboarding. Khoảng &quot;2–8 tuần&quot; nhiều khả năng bị người biên soạn (hoặc công cụ AI hỗ trợ biên soạn) suy diễn/tự thêm vào cho có vẻ cụ thể — <strong>đúng kiểu rủi ro mà chính §1.5.3 ngay phía trên cảnh báo</strong> (ảo giác số liệu trông hợp lý nhưng không có căn cứ). Khuyến nghị: sửa thành diễn đạt đúng với nguồn (&quot;từ nhiều tuần xuống còn vài giờ&quot;, không nêu khoảng số cụ thể), hoặc nếu muốn giữ số liệu cụ thể, phải tìm nguồn khác và dẫn citekey riêng — không gán cho report 2026 Agentic Coding Trends này.</p><p><strong>3.2. &quot;Cycle Time Collapse&quot; nên ghi rõ là cách diễn giải của người biên soạn, không phải tên mục chính thức trong report.</strong> Không bắt buộc sửa, nhưng nên thêm chú thích (hoặc đổi thành tiêu đề tiếng Việt không kèm cụm tiếng Anh trong ngoặc) để không gây hiểu nhầm đây là thuật ngữ Anthropic đặt ra, khác với &quot;Nghịch lý Cộng tác&quot; và &quot;Từ Người thực thi thành Người điều phối&quot; — hai cụm này đúng là tên mục thật trong report.</p><p><strong>3.3. Trùng lặp nội dung với §1.5.2 đã có.</strong> §1.5.2 (dòng 518-521) đã giới thiệu khái niệm &quot;người điều phối và thẩm định (Orchestrator and Reviewer)&quot;. Mục 2 trong đề xuất mới (&quot;Kỹ sư từ Người thực thi trở thành Người điều phối&quot;) triển khai lại cùng ý tưởng ở mức sâu hơn — không sai, nhưng nên thêm một câu nối tham chiếu ngược lại §1.5.2 để người đọc thấy đây là mở rộng, không phải lặp lại độc lập.</p><h2 id="_4-đanh-gia-tong-the" tabindex="-1">4. Đánh giá tổng thể <a class="header-anchor" href="#_4-đanh-gia-tong-the" aria-label="Permalink to &quot;4. Đánh giá tổng thể&quot;">​</a></h2><p>Đề xuất có chất lượng trích dẫn tốt ở phần lớn các claim quan trọng (số liệu 60%/0-20%, case study Augment Code, thuật ngữ &quot;dynamic surge staffing&quot;, tên report, vị trí chèn, citekey) — các phần này đều kiểm chứng được 1:1 với bản PDF gốc. Có đúng 1 lỗi cụ thể cần sửa (mục 3.1) trước khi đưa vào SSoT, vì đây là số liệu bị thêm vào không có nguồn, nằm cạnh chính đoạn văn cảnh báo về rủi ro này.</p><h2 id="_5-khuyen-nghi-quyet-đinh" tabindex="-1">5. Khuyến nghị quyết định <a class="header-anchor" href="#_5-khuyen-nghi-quyet-đinh" aria-label="Permalink to &quot;5. Khuyến nghị quyết định&quot;">​</a></h2><p>Không đề xuất <strong>Approved</strong> ngay. Đề xuất <strong>Request Changes</strong>: sửa mục 3.1 (bỏ hoặc tìm nguồn khác cho &quot;2-8 tuần&quot;), tuỳ chọn sửa mục 3.2-3.3, sau đó có thể đưa vào SSoT.</p><h2 id="_6-tai-lieu-tham-khao-file-goc" tabindex="-1">6. Tài liệu tham khảo / file gốc <a class="header-anchor" href="#_6-tai-lieu-tham-khao-file-goc" aria-label="Permalink to &quot;6. Tài liệu tham khảo / file gốc&quot;">​</a></h2><ul><li><code>C:/Antigravity/KTPMUD/docs/proposals/KTPMUD_Proposal_CH01_Agentic_SDLC_2026_v0.1.0_20261102.md</code> — đề xuất đang được review</li><li><code>https://resources.anthropic.com/hubfs/2026%20Agentic%20Coding%20Trends%20Report.pdf</code> — nguồn gốc, tải và trích xuất text trực tiếp để đối chiếu (442 dòng text, <code>pdftotext -layout</code>)</li><li><code>C:/Antigravity/KTPMUD/chapters/ch01_tong_quan_sdlc.md</code> — file đích, đọc trực tiếp dòng 512-545 và các dòng chứa &quot;Bàn giao&quot;/&quot;CAMS&quot;/&quot;Orchestrator&quot; để kiểm tra nhất quán thuật ngữ</li><li><code>C:/Antigravity/KTPMUD/references/library.bib</code> — kiểm tra trùng citekey</li></ul><h2 id="_7-changelog" tabindex="-1">7. Changelog <a class="header-anchor" href="#_7-changelog" aria-label="Permalink to &quot;7. Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phiên bản</th><th>Ngày</th><th>Thay đổi</th></tr></thead><tbody><tr><td>1.0.0</td><td>02/11/2026</td><td>Tạo review lần đầu, đối chiếu toàn bộ claim với PDF nguồn gốc</td></tr></tbody></table>',19)])])}const m=n(i,[["render",c]]);export{l as __pageData,m as default};
